// Doc oficial ML: "Stock distribuido" / "Stock multi-origen".
//
// Sin user_product_id: item simple, PUT directo /items/{id} con available_quantity.
//
// Con user_product_id: el item separa stock por ubicacion. Hay que:
//   1) GET /user-products/{id}/stock (fresco, YA en este request) para sacar el header
//      x-version (obligatorio para escribir) y la ubicacion actual de deposito propio.
//   2) PUT /user-products/{id}/stock/type/{seller_warehouse|selling_address} con el
//      x-version y el mismo array de locations pero con la cantidad nueva.
// Full (meli_facility) es de solo lectura: no se puede tocar desde aca.
const token = $('Edit Fields').first().json['Access Token'];
const itemId = $json.item_id;
const userProductId = $json.user_product_id;
const nuevoStock = Number($json.nuevo_stock);

function extraerError(e, fallback) {
  const body = e.response?.body ?? e.cause?.response?.body ?? null;
  const statusCode = e.response?.statusCode ?? e.statusCode ?? 400;
  const mensaje = (body && (body.message || body.cause?.[0]?.message)) || e.message || fallback;
  return { success: false, error: mensaje, statusCode };
}

function headerCaseInsensitive(headers, nombre) {
  if (!headers) return undefined;
  const key = Object.keys(headers).find(k => k.toLowerCase() === nombre.toLowerCase());
  return key ? headers[key] : undefined;
}

// Caso simple: sin stock multi-origen.
if (!userProductId) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'PUT',
      url: `https://api.mercadolibre.com/items/${itemId}`,
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: { available_quantity: nuevoStock },
      json: true,
    });
    return [{ json: { success: true, item_id: resp.id, available_quantity: resp.available_quantity } }];
  } catch (e) {
    return [{ json: extraerError(e, 'Error al actualizar el stock en MercadoLibre') }];
  }
}

// Caso multi-origen: leer ubicaciones + x-version fresco.
let stockActual, xVersion;
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.mercadolibre.com/user-products/${userProductId}/stock`,
    headers: { Authorization: `Bearer ${token}` },
    json: true,
    returnFullResponse: true,
  });
  stockActual = resp.body;
  xVersion = headerCaseInsensitive(resp.headers, 'x-version');
} catch (e) {
  return [{ json: extraerError(e, 'No se pudo leer el stock actual del depósito') }];
}

const locations = stockActual?.locations || [];
const depositoLocations = locations.filter(l => l.type === 'seller_warehouse' || l.type === 'selling_address');

if (depositoLocations.length === 0) {
  return [{ json: { success: false, error: 'Este ítem no tiene depósito propio configurado en Mercado Libre (solo Full).' } }];
}
if (depositoLocations.length > 1) {
  return [{ json: { success: false, error: 'Este ítem tiene múltiples depósitos propios; no soportado todavía desde acá.' } }];
}

const tipo = depositoLocations[0].type;
const nuevasUbicaciones = depositoLocations.map(({ type, ...resto }) => ({ ...resto, quantity: nuevoStock }));

try {
  await this.helpers.httpRequest({
    method: 'PUT',
    url: `https://api.mercadolibre.com/user-products/${userProductId}/stock/type/${tipo}`,
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
      'x-version': String(xVersion),
    },
    body: { locations: nuevasUbicaciones },
    json: true,
  });
  return [{ json: { success: true, item_id: itemId, available_quantity: nuevoStock } }];
} catch (e) {
  return [{ json: extraerError(e, 'Error al actualizar el stock del depósito en MercadoLibre') }];
}
